def max_freq(s, max_letters, min_size, max_size):
    n = len(s)
    freq = {}
    best = 0
    for length in range(min_size, max_size + 1):                            # try every allowed length, not just min_size
        for i in range(n - length + 1):
            sub = s[i:i + length]
            if len(set(sub)) <= max_letters:
                freq[sub] = freq.get(sub, 0) + 1
                best = max(best, freq[sub])
    return best


if __name__ == "__main__":
    print(max_freq("aababcaab", 2, 3, 4))

