import java.util.*;

public class Main {
    int maxFreq(String s, int maxLetters, int minSize, int maxSize) {
        int n = s.length();
        Map<String, Integer> freq = new HashMap<>();
        int best = 0;
        for (int length = minSize; length <= maxSize; length++) {                 // try every allowed length, not just minSize
            for (int i = 0; i + length <= n; i++) {
                String sub = s.substring(i, i + length);
                Set<Character> unique = new HashSet<>();
                for (char c : sub.toCharArray()) unique.add(c);
                if (unique.size() <= maxLetters) {
                    freq.merge(sub, 1, Integer::sum);
                    best = Math.max(best, freq.get(sub));
                }
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxFreq("aababcaab", 2, 3, 4));
    }
}

