#include <bits/stdc++.h>
using namespace std;

int maxFreq(string s, int maxLetters, int minSize, int maxSize) {
    int n = (int)s.size();
    unordered_map<string,int> freq;
    int best = 0;
    for (int length = minSize; length <= maxSize; length++) {                   // try every allowed length, not just minSize
        for (int i = 0; i + length <= n; i++) {
            string sub = s.substr(i, length);
            unordered_set<char> unique(sub.begin(), sub.end());
            if ((int)unique.size() <= maxLetters) {
                best = max(best, ++freq[sub]);
            }
        }
    }
    return best;
}

int main() {
    cout << maxFreq("aababcaab", 2, 3, 4) << endl;
    return 0;
}

